import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"事件 API","description":"","frontmatter":{},"headers":[],"relativePath":"modules/skills/events.md","filePath":"modules/skills/events.md","lastUpdated":0}`),a={name:`modules/skills/events.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="事件-api" tabindex="-1">事件 API <a class="header-anchor" href="#事件-api" aria-label="Permalink to “事件 API”">​</a></h1><p>Skills 事件位于 <code>emaki.jiuwu.craft.skills.api.event</code>，同步发布在技能玩家 owner thread。异步施法会先回到 owner thread，再发布 pre/post 事件。</p><table tabindex="0"><thead><tr><th>事件</th><th>触发时机</th><th>Cancellable</th><th>可修改字段</th><th>取消/结果效果</th><th>runtime 路径</th></tr></thead><tbody><tr><td><code>SkillPreCastEvent</code></td><td>条件、冷却、资源检查通过后，执行技能 effect 前</td><td>是</td><td>无</td><td>停止 effect、资源与冷却提交</td><td><code>CastAttemptService</code> 的 active/passive、<code>cast</code> 与 <code>castByTrigger</code> 路径</td></tr><tr><td><code>SkillPostCastEvent</code></td><td>effect 成功，资源与冷却已通过当前 session 提交后</td><td>否</td><td>无</td><td>post 通知，不可回滚</td><td>成功的 <code>CastAttemptService.finalizeAttempt</code>；失败或 source lost 不发</td></tr><tr><td><code>SkillPreUpgradeEvent</code></td><td>升级校验通过后、扣费和摇点前</td><td>是</td><td><code>successRate</code></td><td>停止扣费与升级</td><td><code>SkillUpgradeService</code></td></tr><tr><td><code>SkillUpgradeEvent</code></td><td>升级尝试成功或失败结果已应用后</td><td>否</td><td>无</td><td>post 通知</td><td><code>SkillUpgradeService</code></td></tr><tr><td><code>PlayerSkillSlotChangeEvent</code></td><td>equip、unequip、bind-trigger 写入前</td><td>是</td><td>无</td><td>阻止槽位变更</td><td><code>PlayerSkillStateService</code> 三条状态路径</td></tr></tbody></table><p><code>SkillPostCastEvent</code> 只包含 player、skillId、triggerId，且绝不 Cancellable。Script action/provider 是扩展执行点，不会凭注册本身触发事件；只有实际进入中央 cast/upgrade/slot service 的操作才覆盖这些事件。</p>`,4)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};